package io.knowledgebrain.collaboration;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController
@ConditionalOnProperty(name="brain.collaboration.submission-files.enabled",havingValue="true")
@RequestMapping("/api/groups/{groupId}/studies/{studyId}/assignments/{assignmentId}")
final class SubmissionFilesController {
 record Submitted(SubmissionStore.Submission submission,List<SubmissionFilesStore.File> files){}
 private final StudyController gate;private final AssignmentStore assignments;private final SubmissionFilesStore files;private final SubmissionMediaClient media;private final MeterRegistry metrics;
 SubmissionFilesController(StudyController gate,AssignmentStore assignments,SubmissionFilesStore files,SubmissionMediaClient media,MeterRegistry metrics){this.gate=gate;this.assignments=assignments;this.files=files;this.media=media;this.metrics=metrics;}
 private void writer(StudyController.Access a){if(!Set.of("OWNER","MEMBER").contains(a.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Submission writer required");}
 private void accepting(UUID group,UUID study,UUID assignment,StudyController.Access a){var p=assignments.submissionParent(group,a.space(),study,assignment,false);if(p.studyArchived()||!p.assignment().state().equals("OPEN"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Assignment is not accepting files");}
 private String key(HttpServletRequest r){var keys=Collections.list(r.getHeaders("Idempotency-Key"));if(keys.size()!=1||!keys.getFirst().matches("[0-9a-f]{32}"))throw GroupInput.bad();return keys.getFirst();}
 private void emptyJson(HttpServletRequest r)throws IOException{var n=GroupInput.json(gate.jsonBody(r));if(n==null||!n.isObject()||n.size()!=0)throw GroupInput.bad();}
 @PostMapping("/submission-files") ResponseEntity<?> create(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),assignment=GroupInput.id(assignmentId);String trace=gate.trace(r);var a=gate.participant(group,r,true,trace);writer(a);accepting(group,study,assignment,a);String key=key(r);byte[] bytes=gate.jsonBody(r);if(bytes.length>2048)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Metadata too large");var n=GroupInput.json(bytes);if(n==null||!n.isObject()||n.size()!=4)throw GroupInput.bad();var value=media.call("create",a.space(),assignment,a.actor(),null,key,n,trace);metrics.counter("brain.collaboration.submission.files","operation","allocate").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(value);
 }
 @PostMapping("/submission-files/{mediaId}/{operation}") ResponseEntity<?> upload(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,@PathVariable String mediaId,@PathVariable String operation,HttpServletRequest r)throws IOException{
  if(!Set.of("complete","upload-form").contains(operation))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"File operation unavailable");gate.query(r,Set.of());UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),assignment=GroupInput.id(assignmentId),id=GroupInput.id(mediaId);String trace=gate.trace(r);var a=gate.participant(group,r,true,trace);writer(a);accepting(group,study,assignment,a);emptyJson(r);var v=media.call(operation.equals("complete")?"complete":"upload",a.space(),assignment,a.actor(),id,null,null,trace);metrics.counter("brain.collaboration.submission.files","operation",operation).increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(v);
 }
 @PostMapping("/submissions/with-files") ResponseEntity<?> submit(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),assignment=GroupInput.id(assignmentId);String trace=gate.trace(r);var a=gate.participant(group,r,true,trace);writer(a);long expected=SubmissionController.expected(r);String key=key(r);var n=GroupInput.json(gate.jsonBody(r));if(n==null||!n.isObject()||n.size()!=3||!n.path("content").isString()||!n.path("assignmentVersion").isIntegralNumber()||!n.path("assignmentVersion").canConvertToLong()||!n.path("files").isArray()||n.path("files").size()<1||n.path("files").size()>5)throw GroupInput.bad();String content=n.path("content").asString();long assignmentVersion=n.path("assignmentVersion").asLong();SubmissionInput.validate(content,assignmentVersion);var ids=new ArrayList<UUID>();for(var item:n.path("files")){if(!item.isString())throw GroupInput.bad();ids.add(GroupInput.id(item.asString()));}if(new HashSet<>(ids).size()!=ids.size())throw GroupInput.bad();assignments.get(group,a.space(),study,assignment);
  var refs=new ArrayList<SubmissionFilesStore.File>();for(var id:ids){var v=media.call("get",a.space(),assignment,a.actor(),id,null,null,trace);refs.add(media.file(v,a.space(),assignment,a.actor(),id,true));}var result=files.submit(group,a.space(),study,assignment,a.actor(),expected,assignmentVersion,key,content,refs,trace.substring(3,35));metrics.counter("brain.collaboration.submission.files","operation",result.applied()?"attached":"replayed").increment();return ResponseEntity.status(result.applied()?201:200).eTag(SubmissionController.tag(result.submission().version())).cacheControl(CacheControl.noStore()).body(new Submitted(result.submission(),result.files()));
 }
 @GetMapping("/submissions/{submissionId}/revisions/{version}/files") ResponseEntity<?> list(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,@PathVariable String submissionId,@PathVariable String version,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());gate.empty(r);UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),assignment=GroupInput.id(assignmentId),id=GroupInput.id(submissionId);long attempt=gate.number(version,0,Long.MAX_VALUE);if(attempt<1)throw GroupInput.bad();var a=gate.participant(group,r,false,gate.trace(r));var v=files.get(group,a.space(),study,assignment,id,attempt,a.actor(),a.role().equals("OWNER"));metrics.counter("brain.collaboration.submission.files","operation","read").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(v);
 }
 @PostMapping("/submissions/{submissionId}/revisions/{version}/files/{mediaId}/download") ResponseEntity<?> download(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,@PathVariable String submissionId,@PathVariable String version,@PathVariable String mediaId,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());UUID group=GroupInput.id(groupId),study=GroupInput.id(studyId),assignment=GroupInput.id(assignmentId),id=GroupInput.id(submissionId),file=GroupInput.id(mediaId);long attempt=gate.number(version,0,Long.MAX_VALUE);if(attempt<1)throw GroupInput.bad();String trace=gate.trace(r);var a=gate.participant(group,r,true,trace);emptyJson(r);var v=files.get(group,a.space(),study,assignment,id,attempt,a.actor(),a.role().equals("OWNER"));var ref=v.files().stream().filter(f->f.mediaId().equals(file)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Submitted file unavailable")); // authority already bound to exact submitted attempt
  // Author is authoritative from the retained Collaboration submission, even if removed from Group.
  UUID author=filesAuthor(group,a.space(),study,assignment,id,a.actor(),a.role().equals("OWNER"));var current=media.call("get",a.space(),assignment,author,file,null,null,trace);if(!ref.equals(media.file(current,a.space(),assignment,author,file,true)))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Submitted file metadata differs");var result=media.call("download",a.space(),assignment,author,file,null,null,trace);metrics.counter("brain.collaboration.submission.files","operation","download").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(result);
 }
 private UUID filesAuthor(UUID group,UUID space,UUID study,UUID assignment,UUID id,UUID actor,boolean owner){return files.author(group,space,study,assignment,id,actor,owner);}
}
